//! packs/ggen-release-pack/ontology.ttl's grp:VersionParityProofArtifact, not
//! this file.
//!
//! Version-parity proof (v26.10.10 release-discipline standard, distilled from
//! graphlaw's release engineering): the actually-built package binary's
//! `--version` output must equal the version Cargo.toml declares for the
//! package under test (CARGO_PKG_VERSION). A mismatch means a release tag,
//! a generated standing doc, or the shipped binary is describing different
//! versions -- exactly the drift the publish-dod receipt exists to catch.
//! Asserts on real subprocess output (Chicago: real collaborator, state-based).

use std::process::Command;

#[test]
fn package_binary_version_equals_cargo_pkg_version() {
    // Consumer-agnostic: cargo sets CARGO_BIN_EXE_<bin> for every bin target of
    // the package under test; resolve the primary bin from CARGO_PKG_NAME at
    // runtime so this proof compiles in any consumer without edits.
    let bin_name = std::env::var("CARGO_PKG_NAME").expect("CARGO_PKG_NAME is set by cargo");
    let bin = std::env::var_os(format!("CARGO_BIN_EXE_{bin_name}"))
        .unwrap_or_else(|| {
            panic!("CARGO_BIN_EXE_{bin_name} not set -- is there a [[bin]] named after the package?")
        });
    let out = Command::new(&bin)
        .arg("--version")
        .output()
        .unwrap_or_else(|e| panic!("binary {bin_name:?} should build and run: {e}"));
    assert!(
        out.status.success(),
        "ggen --version exited non-zero: {:?}",
        out.status
    );
    let stdout = String::from_utf8(out.stdout).expect("--version stdout is utf-8");
    let expected = env!("CARGO_PKG_VERSION");
    let reported = stdout.trim().rsplit(' ').next().unwrap_or_default();
    assert!(
        !reported.is_empty(),
        "could not parse a version token from --version output: {stdout:?}"
    );
    assert_eq!(
        reported, expected,
        "binary --version ({reported}) does not equal CARGO_PKG_VERSION ({expected}) -- version drift between built binary and Cargo.toml"
    );
}

